  Record rfH (regs : bvmap 5 word) (mem : word -> option byte) (sp : word) (can : Z) : Prop := RFH {
    R2  : getr regs 2 = sp;
    Rsp16 : (bv_unsigned sp mod 16 = 0)%Z;
    RspLo : (ASP_LO <= bv_unsigned sp)%Z;
